}

Method.Source:
/// <summary>
/// PaffH 24.10.22
/// initialize class
/// </summary>
/// <param name = "_formRun">FormRun</param>
public void initFromFormRun(FormRun _formRun)
{
    formRun = _formRun;
    InventTable_1_ds = formRun.dataHelper().FindDataSource(formDataSourceStr(NDXProdIdent, InventTable_1));
}

/// <summary>
/// PaffH 24.10.22
/// constructor
/// </summary>
/// <param name = "_formRun">FormRun</param>
/// <returns>NDXProdIdentForm</returns>
public static NDXProdIdentForm newFromForm(FormRun _formRun)
{
    NDXProdIdentForm formHandler;
    formHandler = new NDXProdIdentForm();
    formHandler.initFromFormRun(_formRun);
    return formHandler;
}

/// <summary>
/// PaffH 21.04.23
/// set filter to items with data transfer errors
/// </summary>
/// <param name = "_lSet">boolean</param>
void setFilterItemWithErrors(boolean _lSet)
{
    Query   q;
    QueryBuildDataSource qbds, qbds2;
    QueryBuildDataSource qbdsNDXProdIdentProcedureTable;
    QueryBuildDataSource qbdsNDXDataTransferError;
    int i, j, counter, counter2;
    int tableId;

    if (_lSet)
    {
        if (!qSave04)
        {
            qSave04 = new Query(InventTable_1_DS.query());
        }

        q = new Query(qSave04);
        counter = q.childDataSourceCount();
        for (i = 1; i <= counter; i++)
        {
            qbds = q.childDataSourceNo(i);
            counter2 = qbds.childDataSourceCount();
            tableId = qbds.table();
            for (j=1; j <= counter2; j++)
            {
                qbds2 = qbds.childDataSourceNo(j);
                switch (qbds2.table())
                {
                    case tablenum(NDXProdIdentProcedureTable) :
                        qbdsNDXProdIdentProcedureTable = qbds2;
                        break;
                    case tablenum(NDXDataTransferError) :
                        qbdsNDXDataTransferError = qbds2;
                        break;
                }
            }
            if (!qbdsNDXProdIdentProcedureTable)
            {
                qbdsNDXProdIdentProcedureTable = qbds.addDataSource(tablenum(NDXProdIdentProcedureTable));
                qbdsNDXProdIdentProcedureTable.relations(true);
                qbdsNDXProdIdentProcedureTable.fetchMode(QueryFetchMode::One2One);
            }
            if (!qbdsNDXDataTransferError)
            {
                qbdsNDXDataTransferError = qbdsNDXProdIdentProcedureTable.addDataSource(tablenum(NDXDataTransferError));
                qbdsNDXDataTransferError.relations(true);
                qbdsNDXDataTransferError.fetchMode(QueryFetchMode::One2One);
            }
            qbdsNDXProdIdentProcedureTable.joinMode(JoinMode::ExistsJoin);
            qbdsNDXDataTransferError.joinMode(JoinMode::ExistsJoin);
        }
        InventTable_1_DS.query(q);
    }
    else
    {
        if (qSave04)
        {
            InventTable_1_DS.query(qSave04);
            qSave04 = null;
        }
    }
    InventTable_1_DS.executeQuery();
}

/// <summary>
/// PaffH 20.09.22
