/// display only active ProdIdent records with TechniqueId or in general with techniqueIds
/// </summary>
/// <param name = "_filterValue">NDX_ProdIdent_TechniqueID</param>
/// <param name = "_lSet">boolean</param>
void setFilterItemWithTechniqueId(NDXProdIdentTechniqueID _filterValue, boolean _lSet)
{
    Query   q;
    QueryBuildDataSource qbds, qbds2;
    QueryBuildDataSource qbdsNDX_ProdIdent_ProcedureTable;
    QueryBuildDataSource qbdsNDX_ProdIdent_ProcedureLine1;
    QueryBuildDataSource qbdsNDX_ProdIdent_ProcedureLine2;
    QueryBuildDataSource qbdsNDX_ProdIdentTechnique;
    QueryBuildRange qbr;
    int i, j, counter, counter2;
    int tableId;

    if (_lSet)
    {
        if (!qSave02)
        {
            qSave02 = new Query(InventTable_1_DS.query());
        }

        q = new Query(qSave02);
        counter = q.childDataSourceCount();
        for (i = 1; i <= counter; i++)
        {
            qbds = q.childDataSourceNo(i);
            counter2 = qbds.childDataSourceCount();
            tableId = qbds.table();
            for (j=1; j <= counter2; j++)
            {
                qbds2 = qbds.childDataSourceNo(j);
                switch (qbds2.table())
                {
                    case tablenum(NDXProdIdentProcedureTable) :
                        qbdsNDX_ProdIdent_ProcedureTable = qbds2;
                        break;
                    case tablenum(NDXProdIdentProcedureLine1) :
                        qbdsNDX_ProdIdent_ProcedureLine1 = qbds2;
                        break;
                    case tablenum(NDXProdIdentProcedureLine2) :
                        qbdsNDX_ProdIdent_ProcedureLine2 = qbds2;
                        break;
                    case tablenum(NDXProdIdentTechnique) :
                        qbdsNDX_ProdIdentTechnique = qbds2;
                        break;
                }
            }
            if (!qbdsNDX_ProdIdent_ProcedureTable)
            {
                qbdsNDX_ProdIdent_ProcedureTable = qbds.addDataSource(tablenum(NDXProdIdentProcedureTable));
                qbdsNDX_ProdIdent_ProcedureTable.relations(true);
                qbdsNDX_ProdIdent_ProcedureTable.fetchMode(QueryFetchMode::One2One);
            }
            if (!qbdsNDX_ProdIdent_ProcedureLine1)
            {
                qbdsNDX_ProdIdent_ProcedureLine1 = qbdsNDX_ProdIdent_ProcedureTable.addDataSource(tablenum(NDXProdIdentProcedureLine1));
                qbdsNDX_ProdIdent_ProcedureLine1.relations(true);
                qbdsNDX_ProdIdent_ProcedureLine1.fetchMode(QueryFetchMode::One2One);
            }
            if (!qbdsNDX_ProdIdent_ProcedureLine2)
            {
                qbdsNDX_ProdIdent_ProcedureLine2 = qbdsNDX_ProdIdent_ProcedureLine1.addDataSource(tablenum(NDXProdIdentProcedureLine2));
                qbdsNDX_ProdIdent_ProcedureLine2.relations(true);
                qbdsNDX_ProdIdent_ProcedureLine2.fetchMode(QueryFetchMode::One2One);
            }
            if (!qbdsNDX_ProdIdentTechnique)
            {
                qbdsNDX_ProdIdentTechnique = qbdsNDX_ProdIdent_ProcedureLine2.addDataSource(tablenum(NDXProdIdentTechnique));
                qbdsNDX_ProdIdentTechnique.relations(true);
                qbdsNDX_ProdIdentTechnique.fetchMode(QueryFetchMode::One2One);
            }
            if (_filterValue)
            {
                qbr = SysQuery::findOrCreateRange(qbdsNDX_ProdIdentTechnique, fieldnum(NDXProdIdentTechnique, ID));
                qbr.value(_filterValue);
            }
            qbdsNDX_ProdIdent_ProcedureTable.joinMode(JoinMode::ExistsJoin);
            qbdsNDX_ProdIdent_ProcedureLine1.joinMode(JoinMode::ExistsJoin);
            qbdsNDX_ProdIdent_ProcedureLine2.joinMode(JoinMode::ExistsJoin);
            qbdsNDX_ProdIdentTechnique.joinMode(JoinMode::ExistsJoin);
        }
        InventTable_1_DS.query(q);
    }
    else
    {
        if (qSave02)
        {
            InventTable_1_DS.query(qSave02);
            qSave02 = null;
        }
    }
    InventTable_1_DS.executeQuery();
}

